        public LocalOrderChannel(MassGpuBufferManager buffers,int epoch,int[] teams,float[] radii,
            Func<float,TerrainNavigationGrid> navigationFactory,Func<bool> contextCurrent=null,Func<bool> canRefreshAttack=null)
