                for(int i=0;i<orders.Length;i++)if(orders[i].slotPlusOne!=0){used.Add(orders[i].slotPlusOne);if(!replacing.Contains(i)&&p.hp[i]>0)surviving.Add(orders[i].slotPlusOne);}
