int GetLocalTargetSearchCellRadius(float maxTargetRadius)
{
    int radiusFromDistance = (int)ceil(max(0.0, maxTargetRadius) / max(cellSize, 0.0001));
    int configuredLimit = clamp(localTargetSearchCellRadius, 1, LOCAL_TARGET_SEARCH_MAX_CELL_RADIUS);
    return clamp(radiusFromDistance, 1, configuredLimit);
}

// Search cadence counts DECISION passes, not global frames, so it stays aligned with
// the LOD simulation interval for any value (a frame-based gate silently stretched the
// re-target period to lcm(simInterval, 4) frames for non-power-of-two intervals).
bool ShouldSearchForLocalTarget(uint selfIndex, int simInterval)
{
    uint groupIndex = selfIndex / LOCAL_TARGET_SEARCH_GROUP_SIZE;
    uint interval = (uint)max(1, simInterval);
    uint decisionIndex = (frameIndex + groupIndex) / interval;
    uint cadence = max(1u, LOCAL_TARGET_SEARCH_INTERVAL / interval);
    return (decisionIndex % cadence) == 0u;
}

float GetAttackRange(uint index)
{
    UnitTypeSettings settings = GetUnitSettings(index);
    // 统一使用有效射程：远程单位用 projectileRange，近战单位用 attackRange
    return settings.projectileRange > 0.01 ? settings.projectileRange : settings.attackRange;
}

int GetAttackDamage(uint index)
{
    return GetUnitSettings(index).attackDamage;
}

float GetAttackInterval(uint index)
{
    return GetUnitSettings(index).attackInterval;
}

float AttackExitRange(uint selfIndex)
{
    float effectiveRange = GetAttackRange(selfIndex);
    return effectiveRange + max(0.25, GetAgentRadius(selfIndex) * 0.75);
}

float3 ClampVelocity(uint selfIndex, float3 velocity)
{
    velocity.y = 0.0;
    float speedSqr = dot(velocity.xz, velocity.xz);
    float maxSpeed = GetMaxSpeed(selfIndex);
    float maxSpeedSqr = maxSpeed * maxSpeed;
    if (speedSqr > maxSpeedSqr && speedSqr > 0.0001)
        velocity.xz *= maxSpeed * rsqrt(speedSqr);
    return velocity;
}

void ApplyBounds(inout AgentData agent)
{
    float2 minXZ = gridOrigin + boundaryPadding;
    float2 maxXZ = gridOrigin + gridWorldSize - boundaryPadding;

    if (agent.position.x < minXZ.x)
    {
        agent.position.x = minXZ.x;
        agent.velocity.x = abs(agent.velocity.x) * 0.25;
    }
    else if (agent.position.x > maxXZ.x)
    {
        agent.position.x = maxXZ.x;
        agent.velocity.x = -abs(agent.velocity.x) * 0.25;
    }

    if (agent.position.z < minXZ.y)
    {
        agent.position.z = minXZ.y;
        agent.velocity.z = abs(agent.velocity.z) * 0.25;
    }
    else if (agent.position.z > maxXZ.y)
    {
        agent.position.z = maxXZ.y;
        agent.velocity.z = -abs(agent.velocity.z) * 0.25;
    }
}

void FaceDirection(inout AgentData agent, float2 direction)
{
    if (dot(direction, direction) <= 0.0001)
        return;

    agent.rotation.y = degrees(atan2(direction.x, direction.y));
}

float NormalizeAngleDeltaDegrees(float angle)
{
    return angle - 360.0 * floor((angle + 180.0) / 360.0);
}

void SmoothFaceDirectionDt(inout AgentData agent, float2 direction, float deadZoneDistance, float maxDegreesPerSecond, float dt)
{
    float lenSqr = dot(direction, direction);
    float deadZoneSqr = deadZoneDistance * deadZoneDistance;
    if (lenSqr <= max(0.0001, deadZoneSqr))
        return;

    float targetYaw = degrees(atan2(direction.x, direction.y));
    float deltaYaw = NormalizeAngleDeltaDegrees(targetYaw - agent.rotation.y);
    float maxStep = max(1.0, maxDegreesPerSecond) * dt;
    agent.rotation.y += clamp(deltaYaw, -maxStep, maxStep);
}

void SmoothFaceDirection(inout AgentData agent, float2 direction, float deadZoneDistance, float maxDegreesPerSecond)
{
    SmoothFaceDirectionDt(agent, direction, deadZoneDistance, maxDegreesPerSecond, SafeDt());
}

// Alive test against last frame's hp snapshot. All kernels (including the combat kernel
// when it inspects OTHER agents) use the snapshot; only the combat kernel resolves its
// OWN hp for this frame. An agent killed this frame is therefore observed alive by its
// neighbours until next frame — a deterministic one-frame latency.
bool IsAliveIndex(uint index)
{
    return hpReadBuffer[index] > 0;
}

bool IsEnemy(uint selfIndex, uint otherIndex)
{
    if (combatEnabled == 0)
        return false;

    return teamIdReadBuffer[selfIndex] != teamIdReadBuffer[otherIndex];
}

int TeamStanceOf(uint index)
{
#if defined(MASS_LOCAL_ORDERS) && defined(MASS_TERRAIN_ENABLED)
    if(HasLocalOrder(index))return _LocalOrders[index].stance;
#endif
    int teamId = teamIdReadBuffer[index];
    // A teamId outside the allocated range has no stance record. Advance matches what such
    // an agent did before stances existed: it fell through to the attacker branch.
    if (teamId < 0 || teamId >= teamCount)
        return TEAM_STANCE_ADVANCE;

    return teamStanceReadBuffer[teamId];
}

// Gated on combatEnabled so a crowd-only frame (combat disabled) leaves nobody
// holding, exactly as the old defender predicate did.
bool IsHoldStance(uint index)
{
    int stance = TeamStanceOf(index);
    return combatEnabled != 0 && (stance == TEAM_STANCE_HOLD || stance == TEAM_STANCE_HOLD_HERE);
}

// retainExisting: true when validating an agent's CURRENT target (hysteresis applies),
// false for fresh acquisition (strict gates). Hold defenders keep an engaged target out
// to AttackExitRange, mirroring the attacker-side hysteresis — without it, crowd jitter
// across the exact attackRange line produced systematic one-sided trades.
bool TargetIsUsable(uint selfIndex, uint otherIndex, float distSqr, float3 selfPosition, bool retainExisting)
{
    // Explicit Move/Retreat must release existing enemies as well as reject new
    // acquisition; otherwise front ranks keep fighting while only the rear obeys.
    if (TeamStanceOf(selfIndex) == TEAM_STANCE_MOVE_ONLY) return false;

    if (selfIndex == otherIndex || !IsAliveIndex(otherIndex) || !IsEnemy(selfIndex, otherIndex))
        return false;

    if (IsHoldStance(selfIndex))
    {
        float holdRange = retainExisting ? AttackExitRange(selfIndex) : GetAttackRange(selfIndex);
        return distSqr <= holdRange * holdRange;
    }

    // Everyone not holding acquires on aggro radius alone - advancing defenders used to
    // take a separate branch with identical arithmetic. No spawn-anchored chase leash
    // here: it broke the doctrine outright (defenders relocated by their flow field could
    // never acquire targets again); leashing belongs to an explicit order, not to this.
    float acquireRadius = GetTargetAcquireRadius(selfIndex);
    float acquireSqr = acquireRadius * acquireRadius;
    return distSqr <= acquireSqr;
}

bool CurrentTargetIsValid(uint selfIndex, AgentData self, int targetIndex)
{
    if (targetIndex < 0)
        return false;

    uint otherIndex = (uint)targetIndex;
    float2 delta = agentPositionReadBuffer[otherIndex] - self.position.xz;
    bool retainExisting = self.currentState == STATE_ATTACK;
#if defined(MASS_TERRAIN_ENABLED)
    return TargetIsUsable(selfIndex, otherIndex, TerrainDistanceSquared(self.position, agentPositionReadBuffer[otherIndex]), self.position, retainExisting);
#else
    return TargetIsUsable(selfIndex, otherIndex, dot(delta, delta), self.position, retainExisting);
#endif
}

float2 ConfiguredFlowTargetOffset(float2 position, int targetMode, float4 targetPoint, float4 targetArea)
{
    if (targetMode == FLOW_TARGET_POINT)
        return targetPoint.xy - position;

    if (targetMode == FLOW_TARGET_AREA)
    {
        float2 halfSize = max(targetArea.zw, 0.0) * 0.5;
        float2 closest = clamp(position, targetArea.xy - halfSize, targetArea.xy + halfSize);
        return closest - position;
    }

    return 0.0;
}

struct NeighborhoodQueryResult
{
    int bestEnemyIndex;
    float bestEnemyScore;
    float2 separation;
    float2 contactSeparation;
    bool friendlyAhead;
};

uint CurrentEngagementOccupancy(uint targetIndex, uint slot)
{
    uint packed = engagementSlotOccupancyReadBuffer[targetIndex * ENGAGEMENT_SLOT_COUNT + slot];
    uint stamp = frameIndex & 0x00FFFFFFu;
    return (packed >> 8) == stamp ? packed & 0xFFu : 0u;
}

uint CurrentTargetLoad(uint targetIndex)
{
    uint load = 0u;
    [unroll]
    for (uint slot = 0u; slot < ENGAGEMENT_SLOT_COUNT; slot++)
        load += CurrentEngagementOccupancy(targetIndex, slot);
    return load;
}

float TargetLoadCapacity(uint selfIndex, uint targetIndex)
{
    float selfRadius = max(0.05, GetAgentRadius(selfIndex));
    float targetRadius = max(0.05, GetAgentRadius(targetIndex));
    float attackRange = max(0.1, GetAttackRange(selfIndex));
    float engagementRadius = min(max((selfRadius + targetRadius) * 0.8, attackRange * 0.72), attackRange * 0.86);
    float circumference = 6.2831853 * max(engagementRadius, selfRadius + targetRadius);
    float geometricCapacity = floor(circumference / max(0.1, selfRadius * 2.0));
    return clamp(geometricCapacity, 1.0, (float)ENGAGEMENT_SLOT_COUNT);
}

float TargetLoadRatio(uint selfIndex, uint targetIndex)
{
    return (float)CurrentTargetLoad(targetIndex) / TargetLoadCapacity(selfIndex, targetIndex);
}

float TargetSelectionScore(uint selfIndex, uint targetIndex, float distSqr)
{
    float distanceScore = sqrt(max(0.0, distSqr)) / max(0.1, GetTargetAcquireRadius(selfIndex));
    float loadRatio = TargetLoadRatio(selfIndex, targetIndex);
    float loadPenalty = saturate(loadRatio) * 0.30 + max(0.0, loadRatio - 1.0) * 0.15;

    // A stable per-agent affinity breaks up synchronized switching when many agents
    // observe the same one-frame-old load snapshot. Distance still dominates when
    // candidates are meaningfully separated.
    float affinity = Hash01(selfIndex ^ (targetIndex * 0x9E3779B9u)) * 0.45;
    return distanceScore + loadPenalty + affinity;
}

NeighborhoodQueryResult QueryCombatNeighborhood(uint selfIndex, AgentData agent, float maxTargetRadius, bool searchForEnemy, float2 travelForward)
{
    float2 selfPosition = agent.position.xz;
    int2 homeCell = PositionXzToCell(selfPosition);
    float selfRadius = GetAgentRadius(selfIndex);
    int queryCellRadius = searchForEnemy ? GetLocalTargetSearchCellRadius(maxTargetRadius) : 1;

    NeighborhoodQueryResult result;
    result.bestEnemyIndex = -1;
    result.bestEnemyScore = 1e20;
    result.separation = 0.0;
    result.contactSeparation = 0.0;
    result.friendlyAhead = false;
    float bodyRadius = selfRadius * max(0.01, max(abs(agent.scale.x), abs(agent.scale.z)));
    // Every team except the agent's own is hostile (no alliance concept yet), so the sweep
    // walks all teamCount-1 opposing buckets instead of one fixed slot. This is the only
    // place where widening the team dimension actually costs more work per agent. A teamId
    // outside [0, teamCount) has no bucket of its own and disables the sweep rather than
    // reading past the end of the team grid.
    int selfTeamId = teamIdReadBuffer[selfIndex];
    uint teamSlotCount = (uint)max(0, teamCount);
    bool sweepEnemies = searchForEnemy && selfTeamId >= 0 && (uint)selfTeamId < teamSlotCount;

    [loop]
    for (int dz = -queryCellRadius; dz <= queryCellRadius; dz++)
    {
        [loop]
        for (int dx = -queryCellRadius; dx <= queryCellRadius; dx++)
        {
            int2 cell = homeCell + int2(dx, dz);
            if (cell.x < 0 || cell.y < 0 || cell.x >= gridResolution.x || cell.y >= gridResolution.y)
                continue;

            uint cellIndex = CellToIndex(cell);
            if (sweepEnemies)
            {
                [loop]
                for (uint enemyTeamSlot = 0; enemyTeamSlot < teamSlotCount; enemyTeamSlot++)
                {
                    if (enemyTeamSlot == (uint)selfTeamId)
                        continue;

                    uint enemyCellIndex = enemyTeamSlot * gridCellCount + cellIndex;
                    uint enemyCount = min(teamGridCountsReadBuffer[enemyCellIndex], maxAgentsPerCell);
                    for (uint i = 0; i < enemyCount; i++)
                    {
                        uint otherIndex = teamGridAgentIndicesReadBuffer[enemyCellIndex * maxAgentsPerCell + i];
                        if (!IsAliveIndex(otherIndex))
                            continue;

                        float2 toOther = agentPositionReadBuffer[otherIndex] - selfPosition;
#if defined(MASS_TERRAIN_ENABLED)
                        float distSqr = TerrainDistanceSquared(agent.position, agentPositionReadBuffer[otherIndex]);
#else
                        float distSqr = dot(toOther, toOther);
#endif
                        if (TargetIsUsable(selfIndex, otherIndex, distSqr, agent.position, false))
                        {
                            float score = TargetSelectionScore(selfIndex, otherIndex, distSqr);
                            if (score < result.bestEnemyScore)
                            {
                                result.bestEnemyScore = score;
                                result.bestEnemyIndex = (int)otherIndex;
                            }
                        }
                    }
                }
            }

            if (abs(dx) > 1 || abs(dz) > 1)
                continue;

            uint occupantCount = min(gridCountsReadBuffer[cellIndex], maxAgentsPerCell);
            for (uint i = 0; i < occupantCount; i++)
            {
                uint otherIndex = gridAgentIndicesReadBuffer[cellIndex * maxAgentsPerCell + i];
                if (otherIndex == selfIndex || !IsAliveIndex(otherIndex))
                    continue;

                float2 otherPosition = agentPositionReadBuffer[otherIndex];
                float2 toOther = otherPosition - selfPosition;
                float distSqr = dot(toOther, toOther);
                // Positions use the frame snapshot. Scale is immutable spawn data;
                // no neighbor velocity/state is sampled while that neighbor is writing.
                float3 otherScale = agentBuffer[otherIndex].scale;
                float bodyDistance = bodyRadius + GetAgentRadius(otherIndex) * max(0.01, max(abs(otherScale.x), abs(otherScale.z)));
                float forwardDistance = dot(toOther, travelForward);
                float sideDistance = abs(toOther.x * travelForward.y - toOther.y * travelForward.x);
                if (teamIdReadBuffer[otherIndex] == selfTeamId && forwardDistance > 0.001 &&
                    forwardDistance < bodyDistance + max(0.15, bodyRadius * 0.5) && sideDistance < bodyDistance * 0.85)
                    result.friendlyAhead = true;
                if (distSqr < bodyDistance * bodyDistance * 0.81)
                {
                    float2 away = distSqr > 0.000001 ? -toOther * rsqrt(distSqr) : FallbackDirection(selfIndex);
                    result.contactSeparation += away * (bodyDistance * 0.9 - sqrt(max(0.0, distSqr)));
                }
                float minDistance = selfRadius + GetAgentRadius(otherIndex);
                float minDistanceSqr = minDistance * minDistance;
                if (distSqr >= minDistanceSqr)
                    continue;

                float2 separationDelta = selfPosition - otherPosition;
                if (distSqr < 0.000001)
                {
                    separationDelta = FallbackDirection(selfIndex) * 0.001;
                    distSqr = dot(separationDelta, separationDelta);
                }

                float dist = max(sqrt(max(distSqr, 0.000001)), 0.0001);
                result.separation += (separationDelta / dist) * (minDistance - dist);
            }
        }
    }

    return result;
}

// Classifies ONE unit type per dispatch (classifyUnitTypeIndex). Animation time is
// advanced here exactly once per agent per frame because every agent belongs to exactly
// one unit type.
void AppendVisibleAgentForUnitType(uint index, inout AgentData agent)
{
    float3 offset = agent.position - lodCenter;
    offset.y = 0.0;
    float distSqr = dot(offset, offset);
    bool isNear = distSqr <= nearLodRadiusSqr;
    bool isMid = !isNear && distSqr <= midLodRadiusSqr;
    int animationInterval = isNear ? nearAnimationInterval : (isMid ? midAnimationInterval : farAnimationInterval);
    // Without farIncludeDead the mid->far boundary is a hard corpse pop line: bodies
    // render inside it and vanish beyond it as the camera moves.
    bool includeFar = farIncludeDead != 0 || IsAliveIndex(index);

    UpdateAnimationTime(index, agent, animationInterval);

    // Despawned corpses leave the render path entirely: no draw, no shadow, no animation
    // fetch. Reached only on the frame the age first reaches its ceiling - from the next
    // frame the classification kernel returns before it even calls this.
    if (IsCorpseDespawned(agent))
        return;

    // The near ring is the only shadow-casting tier and the same visible list feeds
    // every camera and the ShadowCaster pass: culling it against the main camera's
    // frustum makes shadows of off-screen/behind-camera units pop at the screen edge.
    // Its instance count is bounded by pi*nearRadius^2*density, so exempting it from
    // both distance and frustum culling is cheap; mid/far stay culled.
    if (!isNear)
    {
        // Visibility budget: on km-scale battlefields agents beyond this range are
        // sub-pixel; dropping them caps the worst-case visible instance count.
        if (maxRenderDistanceSqr > 0.0 && distSqr > maxRenderDistanceSqr)
            return;

        if (!IsInsideFrustum(agent.position))
            return;
    }

    if (isNear)
        nearVisibleAgentIndices.Append(index);
    else if (isMid)
        midVisibleAgentIndices.Append(index);
    else if (includeFar)
        farVisibleAgentIndices.Append(index);
}

Assets/Game/Scripts/WarSandboxBattleCont:
using System.Collections.Generic;
using UnityEngine;

namespace MassEngine.Game
{
    /// <summary>
    /// Thin game-layer coordinator for a battle of any number of armies. It translates
    /// designer/player intent into MassEngine runtime overrides; it never writes config
    /// assets and owns no duplicate simulation.
    ///
    /// Army slots are indexed by raw teamId and sized from the scenario. Combat, victory and
    /// navigation are all per team: every army in the scenario owns a slice of the flow field
    /// and takes its own orders.
    /// </summary>
    [DefaultExecutionOrder(-50)]
    [DisallowMultipleComponent]
    [AddComponentMenu("MassEngine/War Sandbox Battle Controller")]
    public sealed class WarSandboxBattleController : MonoBehaviour
    {
        [Header("Engine")]
        public MassEngineManager manager;
        public bool pauseOnStart = true;

        [Header("Runtime")]
        [Min(0)] public int selectedTeam;
        [Min(1f)] public float moveWaypointArrivalRadius = 8f;
        [Range(2, 16)] public int maxMoveRoutePoints = 8;

        [Header("Battle Rules")]
        public WarSandboxBattlefieldConfig battlefieldConfig;
        public WarSandboxGameMode gameMode = WarSandboxGameMode.Annihilation;
        public Vector3 controlPointCenter = Vector3.zero;
        [Min(2f)] public float controlPointRadius = 30f;
        [Min(5f)] public float controlPointCaptureSeconds = 20f;

        [Header("Static Obstacles")]
        public bool staticObstaclesEnabled;
        [Tooltip("Use the custom obstacle array below instead of the built-in two-wall layout.")]
        public bool useCustomStaticObstacleLayout;
        [Min(0f)] public float staticObstacleClearance = 2f;
        public StaticObstacleRect[] staticObstacles =
        {
            new StaticObstacleRect(new Vector2(0f, -90f), new Vector2(14f, 110f)),
            new StaticObstacleRect(new Vector2(0f, 90f), new Vector2(14f, 110f))
        };

        // Indexed by raw teamId and widened by RebuildArmyStates to whatever the scenario
        // fields. An unused teamId in the middle stays an empty army rather than shifting the
        // ones after it, so the index a caller passes always means the same team.
        private ArmyRuntimeState[] armies = BuildArmies(MinimumArmyCount);
        private List<Vector3>[] moveRoutes = BuildMoveRoutes(MinimumArmyCount);
        private static readonly StaticObstacleRect[] DefaultStaticObstacles =
        {
            new StaticObstacleRect(new Vector2(0f, -90f), new Vector2(14f, 110f)),
            new StaticObstacleRect(new Vector2(0f, 90f), new Vector2(14f, 110f))
        };

        // The attacker and defender slots exist even in a scenario that fields neither, because
        // the flow fields, the HUD and the control-point mode all still name those two teams.
        private const int MinimumArmyCount = 2;

        private int[] victoryInitialCounts;
        private int[] victoryAliveCounts;
        private WarSandboxBattlePhase phase = WarSandboxBattlePhase.Setup;
        private WarSandboxBattleResult battleResult;
        private float simulationSpeed = 1f;
        private int controlPointOwnerTeamId = -1;
        private float controlPointCaptureProgress;
        private int[] controlPointZoneCounts;
        private bool initialized;
        private WarSandboxStaticObstaclePresenter obstaclePresenter;
        private WarSandboxBattlefieldConfig appliedBattlefieldConfig;
        private WarSandboxBattlefieldRules? initialBattlefieldRules;

        public string BattlefieldRuleError { get; private set; }
        public string CommandError { get; private set; }
        public event System.Action<WarSandboxSoundCue> FeedbackRequested;
        private readonly WarSandboxTerrainValidation terrainValidation = new WarSandboxTerrainValidation();

        public bool TryResolveGroundPoint(Vector3 point, out Vector3 grounded, out string error)
        {
            grounded = point; error = null;
            ResolveManager();
            if (manager == null) { error = "战场尚未就绪。"; return false; }
            if (!manager.TryGetTerrainContext(out var surface, out _, out error)) return false;
            if (surface == null) return true;
            if (!surface.TrySample(new Vector2(point.x, point.z), out var sample))
            { error = "目标超出地表边界。"; return false; }
            grounded = sample.Position;
            return true;
        }

        public bool TryRaycastGround(Ray ray, float distance, LayerMask mask, out Vector3 point, out string error)
        {
            point = default; error = null;
            ResolveManager();
            if (manager == null) { error = "战场尚未就绪。"; return false; }
            if (!manager.TryGetTerrainContext(out var surface, out _, out error)) return false;
            if (surface != null)
            {
                if (TerrainSurfaceQueries.Raycast(surface, ray, distance, out point)) return true;
                error = "未点击到当前地表。"; return false;
            }
            if (Physics.Raycast(ray, out var hit, distance, mask, QueryTriggerInteraction.Ignore))
            { point = hit.point; return true; }
            error = "未点击到地面。"; return false;
        }

        private bool RejectCommand(string error)
        { CommandError = error; FeedbackRequested?.Invoke(WarSandboxSoundCue.Rejected); return false; }

        public bool TryValidateTerrainDeployment(WarSandboxBattlefieldRules rules, out string error)
        {
            error = null;
            ResolveManager();
            if (manager == null) { error = "战场尚未就绪。"; return false; }
            if (!manager.TryGetTerrainContext(out var surface, out _, out error)) return false;
            if (surface == null) return true;
            if (!WarSandboxDeploymentDraft.TryCapture(manager.scenarioConfig, out var draft, out error)) return false;
            return terrainValidation.TryValidate(manager, new WarSandboxDeploymentDraft(draft.Snapshot(), rules), out _, out error);
        }

        // Queued waypoints are checked without replacing the current manager target. An army
        // cannot cross components, so all initial compositions must reach the requested cell.
        private bool TryResolveMoveTarget(int teamId, Vector3 point, out Vector3 target, out string error)
        {
            target = point; error = null;
            // Reject before projection or obstacle adjustment can hide/propagate invalid input.
            if (float.IsNaN(point.x) || float.IsInfinity(point.x) ||
                float.IsNaN(point.y) || float.IsInfinity(point.y) ||
                float.IsNaN(point.z) || float.IsInfinity(point.z))
            {
                error = "命令被拒绝：目标坐标必须为有限数值。";
                return false;
            }
            ResolveManager();
            if (manager == null) { error = "战场尚未就绪。"; return false; }
            if (!manager.TryGetTerrainContext(out var surface, out var navigation, out error)) return false;
            if (surface == null) { target = manager.ResolvePointOutsideStaticObstacles(point); return true; }
            var xz = new Vector2(point.x, point.z);
            if (navigation == null || !navigation.IsWalkable(xz) || !surface.TrySample(xz, out var sample))
            { error = "命令被拒绝：目标位于禁行地形、障碍或地表边界外。"; return false; }
            if (manager.scenarioConfig == null || manager.scenarioConfig.unitTypes == null)
            { error = "军团部署缺失。"; return false; }
            bool hasFormation = false;
            foreach (var unit in manager.scenarioConfig.unitTypes)
            {
                if (unit == null || unit.teamId != teamId || unit.spawnConfig == null || unit.spawnConfig.unitCount <= 0) continue;
                hasFormation = true;
                var start = unit.spawnConfig.spawnCenter;
                if (!navigation.AreConnected(new Vector2(start.x, start.z), xz))
                { error = "命令被拒绝：该军团有编成无法到达目标连通区。"; return false; }
            }
            if (!hasFormation) { error = "此军团没有已部署编成。"; return false; }
            target = sample.Position;
            return true;
        }

        public WarSandboxBattlePhase Phase { get { return phase; } }
        public WarSandboxBattleResult BattleResult { get { return battleResult; } }
        public float SimulationSpeed { get { return simulationSpeed; } }
        /// <summary>
        /// Signed compatibility view: team 0 is positive, team 1 is negative, and a
        /// later team is represented by the generic owner/progress properties below.
        /// </summary>
        public float ControlPointProgress
        {
            get
            {
                if (controlPointOwnerTeamId == 0)
                    return controlPointCaptureProgress;
                if (controlPointOwnerTeamId == 1)
                    return -controlPointCaptureProgress;
                return 0f;
            }
        }
        public float ControlPointCaptureProgress { get { return controlPointCaptureProgress; } }
        public int ControlPointOwnerTeamId { get { return controlPointOwnerTeamId; } }
        public bool IsControlPointContested
        {
            get
            {
                int occupyingTeams = 0;
                for (int teamId = 0; teamId < (controlPointZoneCounts != null ? controlPointZoneCounts.Length : 0); teamId++)
                {
                    if (controlPointZoneCounts[teamId] > 0)
                        occupyingTeams++;
                }

                return occupyingTeams > 1;
            }
        }
        public int AttackersInControlPoint { get { return GetControlPointUnitCount(0); } }
        public int DefendersInControlPoint { get { return GetControlPointUnitCount(1); } }
        /// <summary>
        /// Armies the roster currently holds, sized from the scenario by RebuildArmyStates.
        /// The HUD iterates this instead of assuming the attacker/defender pair, which is what
        /// makes a third army selectable rather than invisible.
        /// </summary>
        public int ArmyCount { get { return armies != null ? armies.Length : 0; } }
        public ArmyRuntimeState SelectedArmy { get { return GetArmy(selectedTeam); } }
        public BattleTelemetrySnapshot TelemetrySnapshot
        {
            get { return manager != null && manager.Telemetry != null ? manager.Telemetry.Snapshot : default; }
        }

        public int GetControlPointUnitCount(int teamId)
        {
            return controlPointZoneCounts != null && teamId >= 0 && teamId < controlPointZoneCounts.Length
                ? controlPointZoneCounts[teamId]
                : 0;
        }

        private void Reset()
        {
            manager = GetComponent<MassEngineManager>();
        }

        private void Awake()
        {
            appliedBattlefieldConfig = null;
            initialBattlefieldRules = null;
            ResolveManager();
            EnsureBattlefieldRules();
            RebuildArmyStates();
            ApplyStaticObstacleSettings();
        }

        private void Start()
        {
            if (manager == null || !EnsureBattlefieldRules())
                return;

            if (pauseOnStart)
            {
                manager.PauseBattle();
                phase = WarSandboxBattlePhase.Setup;
            }
            else
            {
                phase = manager.IsBattleRunning ? WarSandboxBattlePhase.Running : WarSandboxBattlePhase.Setup;
            }
        }

        private void Update()
        {
            if (!initialized)
                RebuildArmyStates();

            ConfigureControlPointTelemetry();
            ApplyStaticObstacleSettings();
            AdvanceMoveRoutes();
            EvaluateVictory();
            EvaluateControlPoint();
        }

        private void OnDestroy()
        {
            if (Application.isPlaying)
                Time.timeScale = 1f;
            if (manager != null)
                manager.SetStaticObstacles(null, 0f);
        }

        private static ArmyRuntimeState[] BuildArmies(int teamCount)
        {
            ArmyRuntimeState[] built = new ArmyRuntimeState[Mathf.Max(MinimumArmyCount, teamCount)];
            for (int teamId = 0; teamId < built.Length; teamId++)
                built[teamId] = new ArmyRuntimeState { teamId = teamId, displayName = DefaultArmyName(teamId) };

            return built;
        }

        private static List<Vector3>[] BuildMoveRoutes(int teamCount)
        {
            List<Vector3>[] built = new List<Vector3>[Mathf.Max(MinimumArmyCount, teamCount)];
            for (int teamId = 0; teamId < built.Length; teamId++)
                built[teamId] = new List<Vector3>();

            return built;
        }

        /// <summary>
        /// Teams 0 and 1 keep the names the HUD has always shown them under; anything past that
        /// is numbered, because nothing in a many-army battle makes one of them "the defender".
        /// </summary>
        /// <summary>
        /// The army's HUD name. The front line keeps its doctrine names; any further army is
        /// numbered, which is why a third army reads as "第3军团" rather than as another defender.
        /// </summary>
        public static string DefaultArmyName(int teamId)
        {
            if (teamId == 0)
                return "攻方";
            if (teamId == 1)
                return "守方";

            return "第" + (teamId + 1) + "军团";
        }

        /// <summary>
        /// Grows the army slots to cover teamCount, keeping every existing state object so a
        /// standing order survives the widening. Never shrinks: a slot whose units are gone
        /// reports initialUnitCount 0, which the victory rule already treats as "did not field
        /// an army", and dropping it would invalidate a teamId a caller still holds.
        /// </summary>
        private void EnsureArmyCapacity(int teamCount)
        {
            int required = Mathf.Max(MinimumArmyCount, teamCount);
            if (armies != null && armies.Length >= required)
                return;

            ArmyRuntimeState[] grownArmies = BuildArmies(required);
            List<Vector3>[] grownRoutes = BuildMoveRoutes(required);
            if (armies != null)
            {
                for (int teamId = 0; teamId < armies.Length; teamId++)
                {
                    grownArmies[teamId] = armies[teamId];
                    grownRoutes[teamId] = moveRoutes[teamId];
                }
            }

            armies = grownArmies;
            moveRoutes = grownRoutes;
        }

        public ArmyRuntimeState GetArmy(int teamId)
        {
            return teamId >= 0 && teamId < armies.Length ? armies[teamId] : null;
        }

        public bool SelectArmy(int teamId)
        {
            if (teamId < 0 || teamId >= armies.Length)
                return false;

            selectedTeam = teamId;
            return true;
        }

        public bool IssueOrder(ArmyOrder order)
        {
            return IssueOrderInternal(order, true);
        }

        public bool IssueMoveOrder(int teamId, Vector3 target, bool append)
        {
            if (IsTerminalPhase(phase) || !WarSandboxSceneSession.AllowsBattleCommands(this)) return false;
            if (!EnsureBattlefieldRules()) return false;
            ArmyRuntimeState army = GetArmy(teamId);
            if (army == null)
                return false;

            if (!TryResolveMoveTarget(teamId, target, out target, out string error)) return RejectCommand(error);

            List<Vector3> route = moveRoutes[teamId];
            bool hasActiveMoveRoute = army.hasOrder && army.currentOrder.type == ArmyOrderType.Move && route.Count > 0;
            if (!append || !hasActiveMoveRoute)
                return IssueOrder(ArmyOrder.Move(teamId, target));

            if (route.Count >= Mathf.Clamp(maxMoveRoutePoints, 2, 16))
                return RejectCommand("路线已达到航点上限。");

            CommandError = null;
            if(manager!=null&&manager.LocalOrders!=null)manager.NotifyMovementCommand(teamId);
            route.Add(target);
            FeedbackRequested?.Invoke(WarSandboxSoundCue.Command);
            return true;
        }

        public bool SetGameMode(WarSandboxGameMode value)
        {
            if (!WarSandboxSceneSession.AllowsBattleCommands(this)) return false;
            if (phase != WarSandboxBattlePhase.Setup)
                return false;

            gameMode = value;
            ResetControlPointState();
            ConfigureControlPointTelemetry();
            return true;
        }

        public WarSandboxBattlefieldRules CaptureBattlefieldRules()
        {
            return new WarSandboxBattlefieldRules
            {
                gameMode = gameMode,
                controlPointCenter = controlPointCenter,
                controlPointRadius = controlPointRadius,
                controlPointCaptureSeconds = controlPointCaptureSeconds,
                staticObstaclesEnabled = staticObstaclesEnabled,
                staticObstacleClearance = staticObstacleClearance,
                staticObstacles = ResolveStaticObstacles()
            }.Copy();
        }

        public bool TryApplyBattlefieldConfig(WarSandboxBattlefieldConfig config, out string error)
        {
            error = null;
            if (phase != WarSandboxBattlePhase.Setup)
            {
                error = "Battlefield rules can only be applied during Setup.";
                return false;
            }
            if (config == null)
            {
                error = "Choose a battlefield rules asset.";
                return false;
            }
            if (!config.TryCreateSnapshot(out WarSandboxBattlefieldRules snapshot, out error)) return false;
            if (!TryValidateTerrainDeployment(snapshot, out error)) return false;

            ApplyBattlefieldRules(snapshot);
            battlefieldConfig = config;
            appliedBattlefieldConfig = config;
            initialBattlefieldRules = snapshot.Copy();
            BattlefieldRuleError = null;
            return true;
        }

        private bool EnsureBattlefieldRules()
        {
            if (battlefieldConfig == null)
            {
                appliedBattlefieldConfig = null;
                initialBattlefieldRules = null;
                BattlefieldRuleError = null;
                return true;
            }
            if (appliedBattlefieldConfig == battlefieldConfig && initialBattlefieldRules.HasValue)
            {
                BattlefieldRuleError = null;
                return true;
            }
            if (TryApplyBattlefieldConfig(battlefieldConfig, out string error)) return true;
            BattlefieldRuleError = error;
            ResolveManager();
            if (manager != null) manager.PauseBattle();
            return false;
        }

        private void ApplyBattlefieldRules(WarSandboxBattlefieldRules rules)
        {
            gameMode = rules.gameMode;
            controlPointCenter = rules.controlPointCenter;
            controlPointRadius = rules.controlPointRadius;
            controlPointCaptureSeconds = rules.controlPointCaptureSeconds;
            staticObstaclesEnabled = rules.staticObstaclesEnabled;
            staticObstacleClearance = rules.staticObstacleClearance;
            useCustomStaticObstacleLayout = true;
            staticObstacles = rules.Copy().staticObstacles;
            ResetControlPointState();
            ConfigureControlPointTelemetry();
            ApplyStaticObstacleSettings();
        }

        public bool SetStaticObstaclesEnabled(bool value)
        {
            if (!WarSandboxSceneSession.AllowsBattleCommands(this)) return false;
            if (phase != WarSandboxBattlePhase.Setup)
                return false;

            var candidate = CaptureBattlefieldRules(); candidate.staticObstaclesEnabled = value;
            if (!TryValidateTerrainDeployment(candidate, out string error)) return RejectCommand(error);
            CommandError = null;
            staticObstaclesEnabled = value;
            ApplyStaticObstacleSettings();
            return true;
        }

        public int GetStaticObstacleCount()
        {
            StaticObstacleRect[] resolved = ResolveStaticObstacles();
            return staticObstaclesEnabled && resolved != null
                ? Mathf.Min(resolved.Length, StaticObstacleMath.MaxObstacleCount)
                : 0;
        }

        public bool TryGetStaticObstacle(int obstacleIndex, out StaticObstacleRect obstacle)
        {
            obstacle = default;
            StaticObstacleRect[] resolved = ResolveStaticObstacles();
            if (!staticObstaclesEnabled || resolved == null || obstacleIndex < 0 || obstacleIndex >= resolved.Length)
                return false;
            obstacle = resolved[obstacleIndex];
            return obstacle.IsValid;
        }

        public int GetMoveRoutePointCount(int teamId)
        {
            return teamId >= 0 && teamId < moveRoutes.Length ? moveRoutes[teamId].Count : 0;
        }

        public bool TryGetMoveRoutePoint(int teamId, int routeIndex, out Vector3 point)
        {
            point = default;
            if (teamId < 0 || teamId >= moveRoutes.Length || routeIndex < 0 || routeIndex >= moveRoutes[teamId].Count)
                return false;

            point = moveRoutes[teamId][routeIndex];
            return true;
        }

        private bool IssueOrderInternal(ArmyOrder order, bool replaceRoute, bool allowCombatAlongRoute = false)
        {
            if (IsTerminalPhase(phase) || !WarSandboxSceneSession.AllowsBattleCommands(this)) return false;
            if (!EnsureBattlefieldRules()) return false;
            ResolveManager();
            ArmyRuntimeState army = GetArmy(order.teamId);
            if (manager == null || army == null)
                return false;

            if (phase == WarSandboxBattlePhase.Setup &&
                !TryValidateTerrainDeployment(CaptureBattlefieldRules(), out string deploymentError)) return RejectCommand(deploymentError);
            if (order.type != ArmyOrderType.Attack && order.type != ArmyOrderType.Move &&
                order.type != ArmyOrderType.Hold && order.type != ArmyOrderType.Retreat) return false;
            if (order.type == ArmyOrderType.Retreat)
            { order.target = army.spawnCenter; order.hasTarget = true; }
            if (order.type == ArmyOrderType.Move || order.type == ArmyOrderType.Retreat)
            {
                if (!order.hasTarget) return RejectCommand("命令缺少目标。");
                if (!TryResolveMoveTarget(order.teamId, order.target, out order.target, out string error)) return RejectCommand(error);
                // Commit the authoritative target before changing navigation, route or order state.
                // A rejected target must leave every part of the previous command untouched.
                if (IsNavigableTeam(order.teamId) && !manager.TrySetFlowTargetOverride(order.teamId, order.target, out error))
                    return RejectCommand(error);
            }

            if (replaceRoute)
            {
                moveRoutes[order.teamId].Clear();
                if (order.type == ArmyOrderType.Move && order.hasTarget)
                    moveRoutes[order.teamId].Add(order.target);
            }

            switch (order.type)
            {
                case ArmyOrderType.Attack:
                    ClearFlowTarget(order.teamId);
                    ApplyTeamNavigation(order.teamId, true, true);
                    break;

                case ArmyOrderType.Move:
                    if (!order.hasTarget)
                        return false;
                    // Default objective advance may fight while retaining its point target.
                    // Explicit player Move/Retreat keep MoveOnly; the point override still
                    // takes priority over dynamic enemy goals in BuildTeamFlowSettings.
                    ApplyTeamNavigation(order.teamId, true, allowCombatAlongRoute);
                    break;

                case ArmyOrderType.Hold:
                    ClearFlowTarget(order.teamId);
                    ApplyTeamNavigation(order.teamId, false, false);
                    break;

                case ArmyOrderType.Retreat:
                    ApplyTeamNavigation(order.teamId, true, false);
                    break;

                default:
                    return false;
            }

            manager.NotifyMovementCommand(order.teamId);
            CommandError = null;
            army.currentOrder = order;
            army.hasOrder = true;
            bool firstOrder = phase == WarSandboxBattlePhase.Setup;
            playbackRevision++;
            manager.StartBattle();
            phase = WarSandboxBattlePhase.Running;
            FeedbackRequested?.Invoke(firstOrder ? WarSandboxSoundCue.Start : WarSandboxSoundCue.Command);
            return true;
        }

        public bool StartDefaultBattle()
        {
            if (IsTerminalPhase(phase) || !WarSandboxSceneSession.AllowsBattleCommands(this)) return false;
            if (!EnsureBattlefieldRules()) return false;
            if (!initialized)
                RebuildArmyStates();

            // A terrain control-point start is all-or-nothing; do not start one army and
            // report success while another army's unreachable default order was rejected.
            if (gameMode == WarSandboxGameMode.ControlPoint)
                for (int teamId = 0; teamId < armies.Length; teamId++)
                    if (armies[teamId].initialUnitCount > 0 &&
                        !TryResolveMoveTarget(teamId, controlPointCenter, out _, out string error)) return RejectCommand(error);
            bool issuedAnyOrder = false;
            for (int teamId = 0; teamId < armies.Length; teamId++)
            {
                if (armies[teamId].initialUnitCount > 0)
                {
                    issuedAnyOrder |= gameMode == WarSandboxGameMode.ControlPoint
                        ? IssueOrderInternal(ArmyOrder.Move(teamId, controlPointCenter), true, allowCombatAlongRoute: true)
                        : IssueOrder(ArmyOrder.Attack(teamId));
                }
            }

            return issuedAnyOrder;
        }

        public bool RestartWithDefaultOrders()
        {
            ResetBattle();
            return StartDefaultBattle();
        }

        public int GetAliveUnitCount(int teamId)
        {
            if (battleResult.valid && battleResult.TryGetArmy(teamId, out var settled)) return settled.survivors;
            ArmyRuntimeState army = GetArmy(teamId);
            if (army == null)
                return 0;

            BattleTelemetrySnapshot snapshot = TelemetrySnapshot;
            if (!snapshot.valid)
                return army.initialUnitCount;

            // Past the teams the telemetry sample covers GetAliveCount returns 0, which would
            // read as annihilated; fall back to the roster instead of inventing a defeat.
            return teamId < snapshot.TeamCount ? snapshot.GetAliveCount(teamId) : army.initialUnitCount;
        }

        public void StartOrResumeBattle()
        {
            if (IsTerminalPhase(phase) || !WarSandboxSceneSession.AllowsBattleCommands(this)) return;
            if (!EnsureBattlefieldRules()) return;
            ResolveManager();
            if (manager == null)
                return;

            if (phase == WarSandboxBattlePhase.Setup &&
                !TryValidateTerrainDeployment(CaptureBattlefieldRules(), out string error)) { RejectCommand(error); return; }
            CommandError = null;
            bool firstStart = phase == WarSandboxBattlePhase.Setup;
            playbackRevision++;
            manager.StartBattle();
            phase = WarSandboxBattlePhase.Running;
            if (firstStart) FeedbackRequested?.Invoke(WarSandboxSoundCue.Start);
        }

        public bool EndBattle()
        {
            if ((phase != WarSandboxBattlePhase.Running && phase != WarSandboxBattlePhase.Paused) ||
                !WarSandboxSceneSession.AllowsBattleCommands(this) || manager == null) return false;
            CompleteBattle(WarSandboxBattlePhase.Ended, TelemetrySnapshot, WarSandboxVictoryReason.ManualEnd);
            return true;
        }

        private int playbackRevision;
        public int PlaybackRevision=>playbackRevision;
        public void NotifyLocalOrderCommitted()=>FeedbackRequested?.Invoke(WarSandboxSoundCue.Command);

        public void PauseBattle()
        {
            ResolveManager();
            if (manager == null)
                return;

            playbackRevision++;
            manager.PauseBattle();
            if (!IsTerminalPhase(phase))
                phase = WarSandboxBattlePhase.Paused;
        }

        public void TogglePause()
        {
            if (phase == WarSandboxBattlePhase.Running)
                PauseBattle();
            else if (!IsTerminalPhase(phase))
                StartOrResumeBattle();
        }

        public void ResetBattle()
        {
            ResetBattleState(true);
        }

        internal void ResetForDeployment() => ResetBattleState(false);
        internal void ResetForDeployment(WarSandboxBattlefieldRules rules)
        {
            ApplyBattlefieldRules(rules);
            ResetBattleState(false);
        }
        internal void CommitDeploymentRules() => initialBattlefieldRules = CaptureBattlefieldRules().Copy();

        private void ResetBattleState(bool restoreRules)
        {
            if (!WarSandboxSceneSession.AllowsBattleCommands(this)) return;
            ResolveManager();
            if (manager == null || !EnsureBattlefieldRules())
                return;

            manager.PauseBattle();
            if (restoreRules && initialBattlefieldRules.HasValue) ApplyBattlefieldRules(initialBattlefieldRules.Value);
            playbackRevision++;
            manager.ResetScenario();
            manager.PauseBattle();

            for (int i = 0; i < armies.Length; i++)
            {
                armies[i].currentOrder = default;
                armies[i].hasOrder = false;
                moveRoutes[i].Clear();
            }

            simulationSpeed = 1f;
            Time.timeScale = 1f;
            phase = WarSandboxBattlePhase.Setup;
            battleResult = default;
            CommandError = null;
            ResetControlPointState();
            initialized = false;
            RebuildArmyStates();
            ConfigureControlPointTelemetry();
            ApplyStaticObstacleSettings();
        }

        public void SetSimulationSpeed(float speed)
        {
            if (!WarSandboxSceneSession.AllowsBattleCommands(this)) return;
            simulationSpeed = Mathf.Clamp(speed, 0.25f, 4f);
            Time.timeScale = simulationSpeed;
        }

        public void RebuildArmyStates()
        {
            ResolveManager();
            if (manager == null || manager.scenarioConfig == null || manager.scenarioConfig.unitTypes == null)
                return;

            UnitTypeConfig[] unitTypes = manager.scenarioConfig.unitTypes;

            // First pass only sizes the slots; the counting pass below needs them to exist.
            int teamCount = MinimumArmyCount;
            for (int i = 0; i < unitTypes.Length; i++)
            {
                UnitTypeConfig unitType = unitTypes[i];
                if (unitType == null || unitType.spawnConfig == null || unitType.teamId < 0)
                    continue;

                teamCount = Mathf.Max(teamCount, unitType.teamId + 1);
            }

            EnsureArmyCapacity(teamCount);
            EnsureControlPointZoneCounts();

            int[] counts = new int[armies.Length];
            Vector3[] weightedCenters = new Vector3[armies.Length];

            for (int i = 0; i < unitTypes.Length; i++)
            {
                UnitTypeConfig unitType = unitTypes[i];
                if (unitType == null || unitType.spawnConfig == null || unitType.teamId < 0 || unitType.teamId >= armies.Length)
                    continue;

                int count = Mathf.Max(0, unitType.spawnConfig.unitCount);
                counts[unitType.teamId] += count;
                weightedCenters[unitType.teamId] += unitType.spawnConfig.spawnCenter * count;
            }

            for (int teamId = 0; teamId < armies.Length; teamId++)
            {
                armies[teamId].initialUnitCount = counts[teamId];
                armies[teamId].spawnCenter = counts[teamId] > 0
                    ? weightedCenters[teamId] / counts[teamId]
                    : Vector3.zero;
                if (counts[teamId] > 0 && TryResolveGroundPoint(armies[teamId].spawnCenter, out var grounded, out _))
                    armies[teamId].spawnCenter = grounded;
            }

            initialized = false;
            for (int teamId = 0; teamId < counts.Length; teamId++)
                initialized |= counts[teamId] > 0;
        }

        private void EvaluateVictory()
        {
            if (phase != WarSandboxBattlePhase.Running || manager == null || manager.Telemetry == null)
                return;

            BattleTelemetrySnapshot snapshot = manager.Telemetry.Snapshot;
            if (!snapshot.valid || snapshot.totalAgents <= 0)
                return;

            if (victoryInitialCounts == null || victoryInitialCounts.Length != armies.Length)
            {
                victoryInitialCounts = new int[armies.Length];
                victoryAliveCounts = new int[armies.Length];
            }

            for (int teamId = 0; teamId < armies.Length; teamId++)
            {
                victoryInitialCounts[teamId] = armies[teamId].initialUnitCount;
                victoryAliveCounts[teamId] = GetAliveUnitCount(teamId);
            }

            if (!WarSandboxVictory.TryResolveAnnihilation(
                    victoryInitialCounts,
                    victoryAliveCounts,
                    out WarSandboxBattlePhase resultPhase,
                    out int winnerTeamId))
                return;

            CompleteBattle(resultPhase, snapshot, WarSandboxVictoryReason.Annihilation, winnerTeamId);
        }

        private void EvaluateControlPoint()
        {
            if (phase != WarSandboxBattlePhase.Running || gameMode != WarSandboxGameMode.ControlPoint)
                return;

            BattleTelemetrySnapshot snapshot = TelemetrySnapshot;
            if (!snapshot.valid || snapshot.teams == null)
                return;

            int previousOwner = controlPointOwnerTeamId;
            bool wasContested = IsControlPointContested;
            EnsureControlPointZoneCounts();
            int fieldedTeamCount = 0;
            for (int teamId = 0; teamId < armies.Length; teamId++)
            {
                TeamSpatialTelemetry team = snapshot.GetTeam(teamId);
                controlPointZoneCounts[teamId] = team.valid ? Mathf.Max(0, team.observationZoneCount) : 0;
                if (armies[teamId].initialUnitCount > 0)
                    fieldedTeamCount++;
            }

            if (fieldedTeamCount < 2)
                return;

            WarSandboxControlPointState state = WarSandboxControlPoint.ResolveCapture(
                controlPointOwnerTeamId,
                controlPointCaptureProgress,
                controlPointZoneCounts,
                Time.deltaTime,
                controlPointCaptureSeconds);
            controlPointOwnerTeamId = state.ownerTeamId;
            controlPointCaptureProgress = state.progress;
            if (previousOwner != controlPointOwnerTeamId || wasContested != IsControlPointContested)
                FeedbackRequested?.Invoke(WarSandboxSoundCue.ControlPoint);

            if (!state.captured)
                return;

            WarSandboxBattlePhase resultPhase = state.ownerTeamId == 0 && fieldedTeamCount <= 2
                ? WarSandboxBattlePhase.AttackerVictory
                : state.ownerTeamId == 1 && fieldedTeamCount <= 2
                    ? WarSandboxBattlePhase.DefenderVictory
                    : WarSandboxBattlePhase.ArmyVictory;
            CompleteBattle(resultPhase, snapshot, WarSandboxVictoryReason.ControlPoint, state.ownerTeamId);
        }

        private void CompleteBattle(
            WarSandboxBattlePhase resultPhase,
            BattleTelemetrySnapshot snapshot,
            WarSandboxVictoryReason victoryReason,
            int winnerTeamId = -1)
        {
            if (battleResult.valid) return;
            playbackRevision++;
            manager.DisableLocalOrderPrototype();
            phase = resultPhase;
            battleResult = WarSandboxBattleResult.Capture(phase, armies, snapshot, victoryReason, winnerTeamId);
            manager.PauseBattle();
            FeedbackRequested?.Invoke(WarSandboxSoundCue.Finish);
        }

        private void ResetControlPointState()
        {
            controlPointOwnerTeamId = -1;
            controlPointCaptureProgress = 0f;
            if (controlPointZoneCounts == null)
                return;

            for (int teamId = 0; teamId < controlPointZoneCounts.Length; teamId++)
                controlPointZoneCounts[teamId] = 0;
        }

        private void EnsureControlPointZoneCounts()
        {
            int required = armies != null ? armies.Length : MinimumArmyCount;
            if (controlPointZoneCounts == null || controlPointZoneCounts.Length != required)
                controlPointZoneCounts = new int[required];
        }

        private void ConfigureControlPointTelemetry()
        {
            ResolveManager();
            if (manager == null || manager.Telemetry == null)
                return;

            if (!TryResolveGroundPoint(controlPointCenter, out var center, out _)) return;
            manager.Telemetry.ConfigureObservationZone(
                center,
                controlPointRadius,
                gameMode == WarSandboxGameMode.ControlPoint);
        }

        private void AdvanceMoveRoutes()
        {
            if (phase != WarSandboxBattlePhase.Running)
                return;

            BattleTelemetrySnapshot snapshot = TelemetrySnapshot;
            if (!snapshot.valid)
                return;

            for (int teamId = 0; teamId < moveRoutes.Length; teamId++)
            {
                List<Vector3> route = moveRoutes[teamId];
                if (route.Count <= 1)
                    continue;

                TeamSpatialTelemetry team = snapshot.GetTeam(teamId);
                if (!team.valid || !WarSandboxMoveRoute.HasReached(team.centroid, route[0], moveWaypointArrivalRadius))
                    continue;

                if (IssueOrderInternal(ArmyOrder.Move(teamId, route[1]), false))
                    route.RemoveAt(0);
            }
        }

        /// <summary>
        /// Whether the engine allocated a flow field slice for this team. Every team in the
        /// scenario does; the check remains as a guard against an order for a team the engine
        /// never heard of (a stale HUD selection after the scenario shrank, say).
        /// </summary>
        private bool IsNavigableTeam(int teamId)
        {
            return manager != null && teamId >= 0 && teamId < manager.NavigableTeamCount;
        }

        private void ApplyTeamNavigation(int teamId, bool enabled, bool dynamicTargeting)
        {
            if (IsNavigableTeam(teamId))
                manager.SetTeamNavigationOverride(teamId, enabled, dynamicTargeting);
        }

        private void ClearFlowTarget(int teamId)
        {
            if (IsNavigableTeam(teamId))
                manager.ClearFlowTargetOverride(teamId);
        }

        private void ResolveManager()
        {
            if (manager == null)
                manager = GetComponent<MassEngineManager>();
        }

        private void ApplyStaticObstacleSettings()
        {
            ResolveManager();
            StaticObstacleRect[] active = staticObstaclesEnabled ? ResolveStaticObstacles() : null;
            if (manager != null)
                manager.SetStaticObstacles(active, staticObstacleClearance);

            if (!Application.isPlaying)
                return;
            if (obstaclePresenter == null)
                obstaclePresenter = GetComponent<WarSandboxStaticObstaclePresenter>();
            if (obstaclePresenter == null)
                obstaclePresenter = gameObject.AddComponent<WarSandboxStaticObstaclePresenter>();
            if (manager != null && manager.TryGetTerrainContext(out var surface, out _, out _))
                obstaclePresenter.Sync(active, surface);
        }

        private StaticObstacleRect[] ResolveStaticObstacles()
        {
            return useCustomStaticObstacleLayout ? staticObstacles : DefaultStaticObstacles;
        }

        private static bool IsTerminalPhase(WarSandboxBattlePhase value)
        {
            return value == WarSandboxBattlePhase.AttackerVictory ||
                   value == WarSandboxBattlePhase.DefenderVictory ||
                   value == WarSandboxBattlePhase.ArmyVictory ||
                   value == WarSandboxBattlePhase.Draw || value == WarSandboxBattlePhase.Ended;
        }
    }
}

Assets/Game/Scripts/WarSandboxCommandHUD:
using UnityEngine;

namespace MassEngine.Game
{
    /// <summary>
    /// Immediate-mode vertical-slice UI: army selection, orders, pause/speed/reset and
    /// victory display. Move orders consume the next ground click.
    /// </summary>
    [DisallowMultipleComponent]
    [AddComponentMenu("MassEngine/War Sandbox Command HUD")]
    public sealed partial class WarSandboxCommandHUD : MonoBehaviour
    {
        public WarSandboxBattleController controller;
        public Camera commandCamera;
        public LayerMask groundMask = ~0;
        [Min(1f)] public float maxRayDistance = 2000f;
        [Min(240f)] public float panelWidth = 300f;
        public bool showHotkeys = true;
        [Min(0.1f)] public float cameraFollowSharpness = 5f;
        [Min(0f)] public float liveBoundsPadding = 12f;
        public bool showMinimap = true;
        [Min(96f)] public float minimapSize = 180f;

        // Follow target: one army, or every army at once. The old Attackers/Defenders pair had
        // no way to name a third army; the followed team travels in cameraFocusTeamId instead.
        private enum CameraFocusMode
        {
            None,
            Army,
            All
        }

        /// <summary>Armies per row in the selector and the force readout. Two keeps the old layout.</summary>
        private const int ArmyColumns = 2;

        private bool awaitingMoveTarget;
        private ClickFlowTargetSetter legacyClickSetter;
        private bool legacyClickSetterWasEnabled;
        private MyCameraManager cameraManager;
        private string commandFeedback;
        private float feedbackUntil;
        private CameraFocusMode cameraFocusMode;
        private int cameraFocusTeamId;
        // Bottom of the panel content measured at the last repaint. The panel box grows to
        // fit this instead of clipping whenever new controls push past the preferred height.
        private float panelContentHeight;

        private void Reset()
        {
            controller = GetComponent<WarSandboxBattleController>();
            commandCamera = Camera.main;
        }

        private void OnEnable()
        {
            ResolveReferences();
            legacyClickSetter = FindFirstObjectByType<ClickFlowTargetSetter>();
            if (legacyClickSetter != null)
            {
                legacyClickSetterWasEnabled = legacyClickSetter.enabled;
                legacyClickSetter.enabled = false;
            }
        }

        private void OnDisable()
        {
            CloseSelectionPreview();
            runtimeUi?.SetVisible(false);
            if (legacyClickSetter != null)
                legacyClickSetter.enabled = legacyClickSetterWasEnabled;
        }

        private void Update()
        {
            UpdateScopedOrdersP8();
            UpdateSelectionPreviewP7();
            RefreshRuntimeUI();
            if (BlockHotkeys26()) return;
            if (WarSandboxUGUI.IsTyping) return;
            if (WarSandboxSceneSession.Instance != null && WarSandboxSceneSession.Instance.InputBlocked) return;
            if (WarSandboxDeploymentHUD.BlocksInput(controller)) return;
            ResolveReferences();
            if (controller == null)
                return;

            bool cameraNavigation =
                Input.GetMouseButton(1) ||
                Input.GetMouseButton(2) ||
                Input.GetKey(KeyCode.LeftAlt) ||
                Input.GetKey(KeyCode.RightAlt) ||
                !Mathf.Approximately(Input.GetAxis("Mouse ScrollWheel"), 0f);

            if (cameraNavigation)
                cameraFocusMode = CameraFocusMode.None;

            // 1..9 select by roster position, so a third army is reachable without inventing keys.
            int hotkeyArmies = Mathf.Min(ResolveArmyCount(), 9);
            for (int teamId = 0; teamId < hotkeyArmies; teamId++)
            {
                if (Input.GetKeyDown((KeyCode)((int)KeyCode.Alpha1 + teamId)))
                    controller.SelectArmy(teamId);
            }
            if (!cameraNavigation)
            {
                if (Input.GetKeyDown(KeyCode.A))
                    PlayerOrderHotkeyP8(KeyCode.A);
                if (Input.GetKeyDown(KeyCode.M))
                    PlayerOrderHotkeyP8(KeyCode.M);
                if (Input.GetKeyDown(KeyCode.H))
                    PlayerOrderHotkeyP8(KeyCode.H);
                if (Input.GetKeyDown(KeyCode.R))
                    PlayerOrderHotkeyP8(KeyCode.R);
            }
            if (Input.GetKeyDown(KeyCode.Space))
                controller.TogglePause();
            if (Input.GetKeyDown(KeyCode.Return) || Input.GetKeyDown(KeyCode.KeypadEnter))
                StartOrRestartDefaultBattle();
            if (Input.GetKeyDown(KeyCode.Escape))
                CancelMoveTarget();
            if (Input.GetKeyDown(KeyCode.F1))
                FocusArmy(0);
            if (Input.GetKeyDown(KeyCode.F2))
                FocusArmy(1);
            if (Input.GetKeyDown(KeyCode.F3))
                FocusBattlefield();
            if (Input.GetKeyDown(KeyCode.F))
                FocusArmy(controller.selectedTeam);
            if (Input.GetKeyDown(KeyCode.O) && controller.Phase == WarSandboxBattlePhase.Setup)
                ToggleStaticObstacles();

            UpdateCameraFollow();

            if (!awaitingMoveTarget || !Input.GetMouseButtonDown(0) || IsMouseOverInterface())
                return;

            Camera targetCamera = commandCamera != null ? commandCamera : Camera.main;
            if (targetCamera == null)
                return;

            Ray ray = targetCamera.ScreenPointToRay(Input.mousePosition);
            if (!controller.TryRaycastGround(ray, Mathf.Max(1f, maxRayDistance), groundMask, out var point, out string error))
            { SetFeedback(error); if (Feedback25 != null) Feedback25.Result(false, "未下达 · " + error + "\n请重新选点，原命令保留", null, ""); return; }

            IssueMoveTo(point, Input.GetKey(KeyCode.LeftShift) || Input.GetKey(KeyCode.RightShift));
        }

        private void OnGUI()
        {
            if (WarSandboxSceneSession.Instance != null && WarSandboxSceneSession.Instance.InputBlocked) return;
            if (WarSandboxDeploymentHUD.BlocksInput(controller)) return;
            ResolveReferences();
            if (controller == null)
                return;

            DrawSelectionRectangleP7();
            DrawWorldOrderMarkers();
        }

        // Kept temporarily as reference while the uGUI presentation is validated.
        // Runtime controls are rendered exclusively by RefreshRuntimeUI.
        private void DrawLegacyControls()
        {
            bool compactLayout = Screen.height < 340f;
            float controlHeight = compactLayout ? 20f : 24f;
            Rect panel = ResolvePanelRect();
            GUI.Box(panel, GUIContent.none);
            GUILayout.BeginArea(new Rect(panel.x + 8f, panel.y + 6f, panel.width - 16f, panel.height - 12f));

            GUILayout.Label("战争沙盒", GUILayout.Height(compactLayout ? 17f : 20f));
            GUILayout.Label("阶段：" + FormatPhase(controller.Phase), GUILayout.Height(compactLayout ? 17f : 20f));
            var deploymentHud = controller.GetComponent<WarSandboxDeploymentHUD>();
            if (deploymentHud != null && GUILayout.Button(controller.Phase == WarSandboxBattlePhase.Setup ? "配兵布阵" : "返回布阵", GUILayout.Height(controlHeight)))
            {
                awaitingMoveTarget = false;
                deploymentHud.RequestEdit();
            }
            if (!string.IsNullOrEmpty(controller.BattlefieldRuleError))
            {
                GUILayout.Label("战场规则无效：\n" + controller.BattlefieldRuleError,
                    new GUIStyle(GUI.skin.label) { wordWrap = true });
                GUILayout.EndArea();
                return;
            }
            DrawForceSummary(compactLayout);

            if (controller.Phase == WarSandboxBattlePhase.Setup && !compactLayout)
            {
                GUILayout.BeginHorizontal();
                bool annihilation = controller.gameMode == WarSandboxGameMode.Annihilation;
                bool controlPoint = controller.gameMode == WarSandboxGameMode.ControlPoint;
                if (GUILayout.Toggle(annihilation, "歼灭战", GUI.skin.button, GUILayout.Height(controlHeight)) && !annihilation)
                    controller.SetGameMode(WarSandboxGameMode.Annihilation);
                if (GUILayout.Toggle(controlPoint, "据点战", GUI.skin.button, GUILayout.Height(controlHeight)) && !controlPoint)
                    controller.SetGameMode(WarSandboxGameMode.ControlPoint);
                GUILayout.EndHorizontal();

                bool obstacleEnabled = controller.staticObstaclesEnabled;
                string obstacleLabel = obstacleEnabled
                    ? "\u9759\u6001\u969c\u788d [O]  \u5df2\u5f00\u542f"
                    : "\u9759\u6001\u969c\u788d [O]  \u5df2\u5173\u95ed";
                bool requestedObstacleState = GUILayout.Toggle(
                    obstacleEnabled, obstacleLabel, GUI.skin.button, GUILayout.Height(controlHeight));
                if (requestedObstacleState != obstacleEnabled)
                    controller.SetStaticObstaclesEnabled(requestedObstacleState);
            }

            DrawArmySelector(controlHeight);

            ArmyRuntimeState selected = controller.SelectedArmy;
            if (selected != null)
            {
                string order = selected.hasOrder ? FormatOrder(selected.currentOrder.type) : "未下令";
                GUILayout.Label(
                    selected.displayName + "  " + selected.initialUnitCount + " 人  |  " + order,
                    GUILayout.Height(compactLayout ? 17f : 20f));
            }

            GUILayout.Space(compactLayout ? 1f : 4f);
            GUILayout.BeginHorizontal();
            if (GUILayout.Button("进攻 [A]", GUILayout.Height(controlHeight)))
                IssueAttack();
            if (GUILayout.Button(awaitingMoveTarget ? "点击地面…" : "移动 [M]", GUILayout.Height(controlHeight)))
                BeginMoveOrder();
            GUILayout.EndHorizontal();

            GUILayout.BeginHorizontal();
            if (GUILayout.Button("原地防守 [H]", GUILayout.Height(controlHeight)))
                IssueHold();
            if (GUILayout.Button("撤回出生地 [R]", GUILayout.Height(controlHeight)))
                IssueRetreat();
            GUILayout.EndHorizontal();

            GUILayout.Space(compactLayout ? 1f : 4f);
            GUILayout.BeginHorizontal();
            if (IsPreOrPostBattle(controller.Phase))
            {
                string startLabel = controller.Phase == WarSandboxBattlePhase.Setup
                    ? "双方开战 [Enter]"
                    : "再来一局 [Enter]";
                if (GUILayout.Button(startLabel, GUILayout.Height(controlHeight)))
                    StartOrRestartDefaultBattle();
            }
            else
            {
                string pauseLabel = controller.Phase == WarSandboxBattlePhase.Running ? "暂停 [Space]" : "继续 [Space]";
                if (GUILayout.Button(pauseLabel, GUILayout.Height(controlHeight)))
                    controller.TogglePause();
            }
            if (GUILayout.Button("重开", GUILayout.Height(controlHeight)))
            {
                awaitingMoveTarget = false;
                controller.ResetBattle();
                FocusBattlefield();
                SetFeedback("战场已重置");
            }
            GUILayout.EndHorizontal();

            GUILayout.Label("速度", GUILayout.Height(compactLayout ? 17f : 20f));
            GUILayout.BeginHorizontal();
            DrawSpeedButton("0.5×", 0.5f, controlHeight);
            DrawSpeedButton("1×", 1f, controlHeight);
            DrawSpeedButton("2×", 2f, controlHeight);
            DrawSpeedButton("4×", 4f, controlHeight);
            GUILayout.EndHorizontal();

            if (!compactLayout)
            {
                GUILayout.BeginHorizontal();
                if (GUILayout.Button("跟随选中 [F]", GUILayout.Height(controlHeight)))
                    FocusArmy(controller.selectedTeam);
                if (GUILayout.Button("全景 [F3]", GUILayout.Height(controlHeight)))
                    FocusBattlefield();
                GUILayout.EndHorizontal();
            }

            if (awaitingMoveTarget)
                GUILayout.Label(
                    "下一次左键点击地面将下达移动命令；Esc 取消。",
                    GUILayout.Height(compactLayout ? 17f : 36f));
            else if (Time.unscaledTime < feedbackUntil)
                GUILayout.Label(commandFeedback, GUILayout.Height(compactLayout ? 17f : 20f));
            else if (showHotkeys && !compactLayout)
                GUILayout.Label("数字键选军团 · F跟随 · F3全景 · Enter开战 · A/M/H/R下令");

            // Measure what the layout actually used this repaint (area-local coordinates).
            // BeginArea silently clips everything below its fixed height, so the box must be
            // sized from real content, not from the drifting preferredHeight constant.
            if (Event.current.type == EventType.Repaint)
            {
                Rect content = GUILayoutUtility.GetLastRect();
                if (content.yMax > 100f)
                    panelContentHeight = content.yMax;
            }
            GUILayout.EndArea();
            DrawControlPointStatus();
            DrawBattleResultReport();
        }

        private void IssueAttack()
        {
            if (RejectSelectionOrderP7() || RejectInput26) return;
            if (RoutePlayerOrderP8(ArmyOrderType.Attack,Vector3.zero,false,out _)) return;
            awaitingMoveTarget = false;
            bool paused = controller.Phase == WarSandboxBattlePhase.Paused;
            bool success = controller.IssueOrder(ArmyOrder.Attack(controller.selectedTeam));
            if (success) SetFeedback(FormatTeamName(controller.selectedTeam) + "：进攻");
            else SetFeedback(controller.CommandError ?? "当前无法进攻。");
            RecordResult25(success, "进攻", paused);
        }

        private void BeginMoveOrder()
        {
            if (RejectSelectionOrderP7() || RejectInput26) return;
            if (!CaptureMoveIntentP8()) return;
            if (controller == null || controller.SelectedArmy == null || IsTerminalPhase(controller.Phase)) return;
            awaitingMoveTarget = true;
            nextUiRefresh = 0;
            SetFeedback(FormatTeamName(controller.selectedTeam) + "：请选择移动目标");
        }

        private bool IssueMoveTo(Vector3 target, bool append = false)
        {
            if (RejectSelectionOrderP7() || RejectInput26) return false;
            if (RoutePlayerOrderP8(ArmyOrderType.Move,target,append,out bool scopedAccepted)) return scopedAccepted;
            bool paused = controller.Phase == WarSandboxBattlePhase.Paused;
            ArmyRuntimeState selectedArmy = controller.SelectedArmy;
            bool actuallyAppending = append &&
                                     controller.GetMoveRoutePointCount(controller.selectedTeam) > 0 &&
                                     selectedArmy != null && selectedArmy.hasOrder &&
                                     selectedArmy.currentOrder.type == ArmyOrderType.Move;
            if (!controller.IssueMoveOrder(controller.selectedTeam, target, append))
            {
                SetFeedback(controller.CommandError ?? "当前无法下达移动命令。");
                RecordResult25(false, "移动", paused);
                return false;
            }

            awaitingMoveTarget = false;
            SetFeedback(FormatTeamName(controller.selectedTeam) + (actuallyAppending ? "：已追加路线航点" : "：移动目标已更新"));
            RecordResult25(true, "移动", paused, actuallyAppending);
            return true;
        }

